joi_block.script:
if (true == (#LivingRoom_Presence).presenceSensor_presence and (#Kitchen_Smoke).smokeDetector_smoke == true) {
(#LivingRoom_Speaker).speaker_speak("Smoke has been detected in the kitchen")
(#Kitchen_Valve).valve_close()
}

if ((#Kitchen_AirConditioner).airConditioner_airConditionerMode == "heat" and false == all(#PresenceSensor).presenceSensor_presence) {
(#Kitchen_AirConditioner).airConditioner_setAirConditionerMode("auto")
all(#Speaker).speaker_speak("The air conditioner mode has been changed to auto.")
}

if (false == all(#MotionSensor).motionSensor_motion and all(#ContactSensor).contactSensor_contact ==| false) {
all(#Camera).camera_captureImage()
all(#Speaker).speaker_speak("Warning")
}

if (1000 <= (#Study_AQ).airQualitySensor_carbonDioxide and (#Study_AP).airPurifier_airPurifierMode == "sleep") {
(#Study_AP).airPurifier_setAirPurifierMode("auto")
(#Study_Speaker).speaker_speak("Switching the air purifier to auto mode")
}

if (50 > (#Garden_Illum).lightSensor_brightness and (#Terrace_Light).switch_switch == false) {
(#Terrace_Light).light_moveToBrightness(100.0, 0.0)
all(#Speaker).speaker_speak("The terrace light has been turned on.")
}

t1 = (#LivingRoom_TempSensor).temperatureSensor_temperature
t2 = (#Bedroom_TempSensor).temperatureSensor_temperature
if (28 <= t1 or t2 >= 30) {
(#LivingRoom_AC).switch_on()
}

lux = (#LivingRoom_LightSensor).lightSensor_brightness
if (200 >= lux) {
(#LivingRoom_Light).light_moveToBrightness(100.0, 0.0)
}
else {
if (lux >= 500) {
(#LivingRoom_Light).light_moveToBrightness(30.0, 0.0)
}
else {
(#LivingRoom_Light).light_moveToBrightness(60.0, 0.0)
}
}

livingRoomHumidity = (#LivingRoom_HumiditySensor).humiditySensor_humidity
bedroomHumidity = (#Bedroom_HumiditySensor).humiditySensor_humidity
if (30 >= livingRoomHumidity or bedroomHumidity <= 30) {
(#LivingRoom_Humidifier).switch_on()
}

if (true == (#Entrance_MotionSensor).motionSensor_motion or (#Balcony_MotionSensor).motionSensor_motion == true) {
(#LivingRoom_Speaker).speaker_speak("Motion is detected at the entrance or motion is detected on the balcony")
}

wait until((#Bedroom_MB).multiButton_button1 == "pushed")
current = (#Bedroom_Light).light_currentBrightness
if (80 <= current) {
(#Bedroom_Light).light_moveToBrightness(10.0, 0.0)
}
else {
(#Bedroom_Light).light_moveToBrightness(80.0, 0.0)
}

t1 = (#WineCellar_TempSensor).temperatureSensor_temperature
delay(1 HOUR)
t2 = (#WineCellar_TempSensor).temperatureSensor_temperature
if (2 <= t2 - t1) {
(#LivingRoom_Speaker).speaker_speak("The wine cellar temperature rose by at least 2 degrees.")
}

phase := 0
if (0 == phase) {
wait until(all(#ContactSensor).contactSensor_contact ==| false)
    phase = 1
    all(#Speaker).speaker_speak("Welcome")
}
else {
all(#Speaker).speaker_speak("Welcome")
}

phase := 0
if (0 == phase) {
wait until(all(#ContactSensor).contactSensor_contact ==| true)
    phase = 1
    all(#Siren).siren_setSirenMode("police")
}
else {
all(#Siren).siren_setSirenMode("police")
}

phase := 0
if (0 == phase) {
wait until((#Entrance_ContactSensor).contactSensor_contact == false)
    phase = 1
    if ((#Main_DoorLock).doorLock_doorLockState != "closed") {
all(#Speaker).speaker_speak("The safe is open")
}
}
else {
if ((#Main_DoorLock).doorLock_doorLockState != "closed") {
all(#Speaker).speaker_speak("The safe is open")
}
}

phase := 0
if (0 == phase) {
wait until(all(#SmokeDetector).smokeDetector_smoke ==| true)
    phase = 1
    all(#Siren).siren_setSirenMode("emergency")
    delay(5 SEC)
all(#Switch).switch_off()
}
else {
all(#Siren).siren_setSirenMode("emergency")
    delay(5 SEC)
all(#Switch).switch_off()
}

phase := 0
if (0 == phase) {
wait until((#Main_Charger).charger_voltage <= 4000)
    phase = 1
    all(#Speaker).speaker_speak("The charging voltage is low")
}
else {
all(#Speaker).speaker_speak("The charging voltage is low")
}

phase := 0
if (0 == phase) {
wait until((#Main_Fan).fan_speed == 0)
    phase = 1
    all(#Speaker).speaker_speak("Please check the fan")
}
else {
all(#Speaker).speaker_speak("Please check the fan")
}

phase := 0
if (0 == phase) {
wait until(all(#MotionSensor).motionSensor_motion ==| true)
    phase = 1
    all(#Camera).camera_captureImage()
}
else {
all(#Camera).camera_captureImage()
}

phase := 0
if (0 == phase) {
wait until((#P_AQ).airQualitySensor_carbonDioxide > 880)
    phase = 1
    (#P_Speaker).speaker_speak("CO2 level danger")
}
else {
(#P_Speaker).speaker_speak("CO2 level danger")
}

phase := 0
if (0 == phase) {
wait until(all(#PresenceSensor).presenceSensor_presence ==| true)
    phase = 1
    (#F1_Siren).siren_setSirenMode("emergency")
    delay(3 SEC)
(#F1_Siren).switch_off()
}
else {
(#F1_Siren).siren_setSirenMode("emergency")
    delay(3 SEC)
(#F1_Siren).switch_off()
}

phase := 0
if (0 == phase) {
wait until((#Lobby_Mot).motionSensor_motion == true)
    phase = 1
    (#Lobby_Cam).camera_captureImage()
}
else {
(#Lobby_Cam).camera_captureImage()
}

phase := 0
if (0 == phase) {
wait until((#K_Smoke).smokeDetector_smoke == true)
    phase = 1
    (#LR_Speaker).speaker_speak("Fire outbreak")
}
else {
(#LR_Speaker).speaker_speak("Fire outbreak")
}

n := 0
if (0 == n % 2) {
all(#Valve).valve_open()
}
else {
all(#Valve).valve_close()
}
n = n + 1

n := 0
if (0 == n % 2) {
(#LivingRoom_AirPurifier).airPurifier_setAirPurifierMode("sleep")
}
else {
(#LivingRoom_AirPurifier).airPurifier_setAirPurifierMode("auto")
}
n = n + 1

n := 0
if (0 == n % 2) {
all(#WindowCovering).windowCovering_upOrOpen()
}
else {
all(#WindowCovering).windowCovering_downOrClose()
}
n = n + 1

n := 0
if (0 == n % 2) {
all(#AirPurifier).airPurifier_setAirPurifierMode("sleep")
}
else {
all(#AirPurifier).airPurifier_setAirPurifierMode("high")
}
n = n + 1

