else {
(#BR_Win).windowCovering_downOrClose()
}
n = n + 1

n := 0
if (0 == n % 2) {
(#MR_AC).airConditioner_setTargetTemperature(25.0)
}
else {
(#MR_AC).airConditioner_setTargetTemperature(20.0)
}
n = n + 1

if (false == (#F1_Presence).presenceSensor_presence) {
all(#Switch).switch_off()
}
delay(1 HOUR)
if ((#F1_Presence).presenceSensor_presence == false) {
all(#Switch).switch_off()
}

temp = (#Living_Temp).temperatureSensor_temperature
if (20 <= temp and temp < 30) {
all(#AirConditioner).airConditioner_setAirConditionerMode("auto")
}
else {
if (temp >= 30) {
all(#AirConditioner).airConditioner_setAirConditionerMode("cool")
}
}

temp = (#Inside_TemperatureSensor).temperatureSensor_temperature
if (25 <= temp) {
all(#Switch).switch_on()
all(#AirConditioner).airConditioner_setAirConditionerMode("cool")
}
else {
all(#Switch).switch_off()
}

if ((#Clock).clock_weekday == "monday") {
break
}
if (true == (#Fac_Pump_1).switch_switch) {
(#Fac_Pump_1).switch_off()
(#EmailProvider).emailProvider_sendMail("test@example.com", "Risk", "A pump is turned on")
}

if (true == (#LivingRoom_MotionSensor).motionSensor_motion or (#Bedroom_MotionSensor).motionSensor_motion == true) {
(#LivingRoom_Speaker).speaker_speak("Motion detected in the living room or bedroom.")
}

l1 = (#LivingRoom_LightSensor).lightSensor_brightness
l2 = (#Bedroom_LightSensor).lightSensor_brightness
if (100 >= l1 and l2 <= 100) {
(#LivingRoom_MoodLight).switch_on()
}

living_temp = (#LivingRoom_TempSensor).temperatureSensor_temperature
bedroom_temp = (#Bedroom_TempSensor).temperatureSensor_temperature
if (25 <= living_temp and bedroom_temp >= 25) {
(#LivingRoom_Fan).switch_on()
}

n := 0
if (10 <= n) {
break
}
(#MeetingRoom_Camera).camera_captureImage()
n = n + 1

